  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Mouse Membuat Kerja Lambat$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Rata-rata pengguna komputer menghabiskan waktu berjam-jam setiap minggu hanya untuk menggerakkan kursor mouse ke menu yang itu-itu saja. Setiap klik memutus alur kerja, membuat pekerjaan mengetik dokumen, mengelola file, atau browsing menjadi jauh lebih lambat daripada yang seharusnya. Padahal, hampir semua perintah umum memiliki jalan pintas keyboard yang jauh lebih cepat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Mengapa Shortcut Lebih Cepat$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Tangan manusia bergerak lebih cepat saat tetap di keyboard (prinsip minimal perpindahan). Studi produktivitas menunjukkan shortcut bisa menghemat hingga beberapa detik per tindakan; dikalikan ratusan tindakan per hari, penghematannya signifikan. Shortcut juga mengurangi ketegangan pergelangan tangan karena berkurangnya gerakan mouse.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat yang Diperlukan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY['Keyboard standar (laptop maupun eksternal)', 'Catatan kecil atau sticky note untuk menempel shortcut yang sedang dihafal', 'Aplikasi yang ingin dikuasai (misalnya Word, Excel, browser)']::text[])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Kuasai Shortcut Bertahap$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY['Hafalkan 5 shortcut universal dulu: Ctrl+C (salin), Ctrl+V (tempel), Ctrl+X (potong), Ctrl+Z (batalkan), Ctrl+S (simpan). Pakai selama seminggu sampai otomatis.', 'Tambahkan navigasi teks: Ctrl+panah untuk lompat per kata, Shift+panah untuk seleksi, Ctrl+A untuk pilih semua.', 'Kuasai manajemen jendela: Alt+Tab (pindah aplikasi), Win+D (tampilkan desktop), Win+panah (atur posisi jendela).', 'Pelajari shortcut browser: Ctrl+T (tab baru), Ctrl+Shift+T (buka tab yang tertutup), Ctrl+L (fokus address bar).', 'Untuk pengguna macOS, ganti Ctrl dengan Cmd (Command) untuk sebagian besar shortcut di atas.']::text[])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Kesalahan Umum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Jangan menghafal 50 shortcut sekaligus — akan frustrasi dan kembali ke mouse. Kesalahan umum: menekan Ctrl+W tanpa sadar (menutup tab), atau Ctrl+Shift+Delete yang menghapus riwayat browser. Pelajari fungsi shortcut baru sebelum dipakai di dokumen penting.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Tindak Lanjut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Uji diri: kerjakan tugas biasa (misalnya memformat dokumen satu halaman) tanpa menyentuh mouse selama 5 menit. Jika bisa menyalin, menempel, menyimpan, dan berpindah aplikasi hanya dengan keyboard, target tercapai. Setelah nyaman, pelajari shortcut khusus aplikasi yang paling sering dipakai (misalnya F2 rename di Excel, Ctrl+B/I/U format teks) dan cetak daftarnya sebagai pengingat.$$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Mata Merah yang Mengganggu$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Bangun pagi dengan mata merah, perih, dan berair tentu mengganggu aktivitas. Banyak orang langsung meneteskan obat mata bebas tanpa tahu penyebabnya, padahal penanganan yang salah bisa memperburuk kondisi. Artikel ini membantu mengenali penyebab umum mata merah dan langkah aman di rumah. Informasi ini bersifat umum dan bukan pengganti nasihat medis — konsultasikan ke dokter bila ragu atau kondisi memburuk.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Penyebab Umum Mata Merah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 3, jsonb_build_object('items', to_jsonb(ARRAY['Kelelahan dan kurang tidur: pembuluh darah mata melebar, biasanya hilang setelah istirahat.', 'Alergi: disertai gatal dan bersin, dipicu debu, serbuk sari, atau bulu hewan.', 'Iritasi: asap rokok, klorin kolam renang, atau paparan layar terlalu lama.', 'Konjungtivitis (mata belekan): mata merah dengan kotoran mata, bisa menular.', 'Benda asing atau goresan kornea: mata merah disertai nyeri tajam dan sensitif cahaya.']::text[])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Pertolongan Pertama di Rumah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY['Kompres dingin dengan kain bersih selama 10-15 menit untuk mengurangi kemerahan.', 'Istirahatkan mata dari layar dan hindari mengucek mata.', 'Gunakan air mata buatan (artificial tears) tanpa pengawet bila mata terasa kering.', 'Jaga kebersihan: cuci tangan sebelum menyentuh area mata, ganti sarung bantal.']::text[])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Risiko: Jangan Asal Tetes Obat$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Obat tetes mata pemutih (mengandung vasokonstriktor) hanya menyamarkan kemerahan dan bisa menimbulkan ketergantungan bila dipakai rutin. Obat tetes antibiotik atau steroid tanpa resep dokter berisiko menutupi infeksi serius atau menaikkan tekanan bola mata.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Tanda Bahaya: Segera ke Dokter$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY['Nyeri mata hebat atau penglihatan kabur/menurun.', 'Sensitif cahaya ekstrem atau mata sangat berair.', 'Mata merah setelah trauma/benturan atau terkena bahan kimia.', 'Kemerahan tidak membaik dalam 2-3 hari atau disertai demam.', 'Keluar cairan nanah dalam jumlah banyak.']::text[])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pencegahan Sehari-hari$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Tidur cukup 7-8 jam, terapkan aturan 20-20-20 saat memakai layar (setiap 20 menit, alihkan pandangan ke 20 kaki selama 20 detik), pakai kacamata pelindung saat berenang atau bekerja dengan debu, dan jangan berbagi handuk atau kosmetik mata.$$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Siapa Suku Bajo?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Suku Bajo (sama Bajau) adalah kelompok etnis yang tersebar di perairan Indonesia timur, Malaysia, dan Filipina selatan. Di Indonesia mereka banyak bermukim di Sulawesi, Nusa Tenggara, Maluku, dan Kalimantan. Julukan mereka: manusia laut, karena sebagian besar hidupnya dihabiskan di atas perahu dan di dalam air.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Rumah di Atas Air$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Permukiman Bajo umumnya berupa rumah panggung di atas laut dangkal, dihubungkan jembatan kayu. Dahulu banyak keluarga Bajo hidup nomaden di atas perahu lepa, berpindah mengikuti musim ikan. Kini sebagian telah menetap, tetapi laut tetap menjadi sumber kehidupan utama mereka.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Penyelam Ulung$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Orang Bajo terkenal mampu menyelam bebas hingga kedalaman belasan meter selama beberapa menit tanpa alat bantu modern. Penelitian menunjukkan limpa mereka cenderung lebih besar dari rata-rata manusia, yang membantu menyimpan oksigen lebih banyak saat menyelam. Kemampuan ini dipelajari sejak kecil dan menjadi modal utama mencari nafkah.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Mata Pencaharian dan Kearifan Lokal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Mayoritas Bajo berprofesi sebagai nelayan tradisional. Mereka mengenal musim, arus, dan tanda-tanda alam dengan sangat baik. Sebagian komunitas memiliki aturan adat tentang wilayah tangkap dan larangan merusak terumbu karang, yang secara tidak langsung menjaga kelestarian laut.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Tantangan Modern$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Perubahan iklim, kerusakan terumbu karang, dan regulasi perikanan modern menekan cara hidup tradisional Bajo. Banyak generasi muda merantau atau beralih profesi. Sebagian komunitas kini mengembangkan ekowisata bahari sebagai sumber penghasilan baru yang tetap menghormati laut.$$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Apa Itu Silikon?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Silikon (simbol Si, nomor atom 14) adalah unsur metaloid: sifatnya di antara logam dan nonlogam. Ia adalah unsur kedua terbanyak di kerak bumi setelah oksigen, terutama dalam bentuk pasir (silika, SiO2) dan mineral silikat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Sifat Kunci: Semikonduktor$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Silikon murni adalah semikonduktor: menghantarkan listrik lebih buruk dari logam tetapi lebih baik dari isolator. Sifat inilah yang membuatnya istimewa. Dengan menambahkan sedikit pengotor (doping) seperti fosfor atau boron, daya hantarnya bisa diatur presisi — dasar dari semua transistor modern.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Dari Pasir Menjadi Chip$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Pasir kuarsa dilebur dan dimurnikan hingga kemurnian ekstrem (99,9999999% atau 9N). Silikon cair kemudian ditarik perlahan menjadi batangan kristal tunggal (ingot), dipotong menjadi wafer tipis, lalu diproses dengan litografi untuk mencetak miliaran transistor dalam satu chip.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Peran dalam Teknologi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Hampir semua prosesor komputer, memori, dan sensor dibuat dari silikon. Panel surya juga memakai silikon untuk mengubah cahaya menjadi listrik. Tanpa silikon murni, tidak ada smartphone, laptop, atau internet seperti sekarang.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Silikon vs Silicone$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Jangan tertukar: silikon (silicon) adalah unsur kimia, sedangkan silikone (silicone) adalah polimer sintetis berbahan dasar silikon yang dipakai untuk sealant, peralatan dapur, dan implan medis. Keduanya berbeda wujud dan fungsi.$$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, siswa diharapkan mampu: (1) menjelaskan pengertian hortatory exposition text, (2) mengidentifikasi struktur teksnya, (3) mengenali ciri kebahasaannya, dan (4) menulis hortatory exposition sederhana.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian Hortatory Exposition$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Hortatory exposition adalah teks yang bertujuan meyakinkan pembaca bahwa sesuatu seharusnya atau tidak seharusnya dilakukan. Kata hortatory berasal dari hortative yang berarti bersifat anjuran atau ajakan. Berbeda dengan analytical exposition yang hanya menjelaskan, hortatory selalu diakhiri rekomendasi tindakan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Struktur Teks$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY['Thesis: pernyataan pendapat/isu yang diangkat penulis.', 'Arguments: alasan-alasan yang mendukung pendapat, biasanya 2-3 argumen.', 'Recommendation: anjuran atau saran tindakan yang sebaiknya dilakukan pembaca.']::text[])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Ciri Kebahasaan dan Contoh$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Hortatory exposition memakai simple present tense, kata kerja mental/material (think, believe, should, must), penghubung penalaran (firstly, therefore, in conclusion), dan modalitas (should, ought to, had better). Contoh: Thesis: Students should bring their own tumblers. Arguments: Firstly, it reduces plastic waste. Secondly, it saves money. Recommendation: Schools should encourage reusable tumblers every day.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Latihan Soal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY['Apa tujuan utama hortatory exposition text?', 'Sebutkan tiga bagian struktur hortatory exposition!', 'Apa perbedaan hortatory dan analytical exposition?', 'Tulis satu kalimat recommendation dengan kata should!']::text[])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY['Meyakinkan pembaca agar melakukan atau tidak melakukan sesuatu (bersifat anjuran).', 'Thesis, arguments, recommendation.', 'Hortatory diakhiri rekomendasi tindakan, sedangkan analytical hanya menjelaskan tanpa rekomendasi.', 'Contoh jawaban: You should exercise regularly to stay healthy. (jawaban lain yang memakai should dan bersifat anjuran diterima)']::text[])));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, siswa diharapkan mampu: (1) menjelaskan pengertian volume, (2) menghitung volume kubus dan balok, (3) menghitung volume prisma segitiga dan tabung, serta (4) menyelesaikan soal cerita tentang volume.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Apa Itu Volume?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Volume adalah ukuran besarnya ruang yang ditempati suatu benda tiga dimensi. Satuan volume biasanya kubik, misalnya cm3 (sentimeter kubik) atau m3 (meter kubik). Bayangkan mengisi kotak dengan kubus-kubus kecil berukuran 1 cm: banyaknya kubus kecil itulah volume kotak.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Volume Kubus dan Balok$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY['Kubus: semua sisinya sama panjang. Rumus: V = s x s x s (s = panjang rusuk). Contoh: kubus dengan rusuk 4 cm, volumenya 4 x 4 x 4 = 64 cm3.', 'Balok: panjang, lebar, tinggi bisa berbeda. Rumus: V = p x l x t. Contoh: balok 5 cm x 3 cm x 2 cm, volumenya 5 x 3 x 2 = 30 cm3.']::text[])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Volume Prisma dan Tabung$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY['Prisma segitiga: V = luas alas x tinggi prisma. Alasnya segitiga, jadi luas alas = 1/2 x a x t segitiga. Contoh: alas segitiga 6 cm x 4 cm, tinggi prisma 10 cm. Luas alas = 12 cm2, volume = 12 x 10 = 120 cm3.', 'Tabung: V = luas lingkaran alas x tinggi = phi x r x r x t. Gunakan phi = 22/7 jika jari-jari kelipatan 7, atau 3,14 jika tidak.']::text[])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Contoh Soal dan Latihan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Contoh: akuarium balok 60 cm x 30 cm x 40 cm. V = 60 x 30 x 40 = 72.000 cm3 = 72 liter air (1 liter = 1.000 cm3). Sekarang kerjakan: (1) volume kubus rusuk 7 cm, (2) volume balok 8 cm x 5 cm x 4 cm, (3) volume tabung r = 7 cm, t = 10 cm dengan phi = 22/7.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kunci Jawaban$$));
